import { create } from 'zustand';
import { persist, createJSONStorage } from 'zustand/middleware';
import notification from '../utils/notification';

export const useCartStore = create(
  persist(
    (set, get) => ({
      cartItems: [],
      isCartOpen: false,

      addToCart: (product, quantity = 1) => {
        const { cartItems } = get();
        const existingItem = cartItems.find(item => item.id === product.id);
        
        if (existingItem) {
          notification.success(`Updated ${product.name} quantity in cart`);
          set({
            cartItems: cartItems.map(item => 
              item.id === product.id 
                ? { ...item, quantity: item.quantity + quantity }
                : item
            )
          });
        } else {
          notification.success(`Added ${product.name} to cart`);
          set({
            cartItems: [...cartItems, { ...product, quantity }]
          });
        }
      },

      removeFromCart: (productId) => {
        set(state => ({
          cartItems: state.cartItems.filter(item => item.id !== productId)
        }));
        notification.info('Item removed from cart');
      },

      updateQuantity: (productId, quantity) => {
        if (quantity <= 0) {
          get().removeFromCart(productId);
          return;
        }
        set(state => ({
          cartItems: state.cartItems.map(item => 
            item.id === productId ? { ...item, quantity } : item
          )
        }));
      },

      clearCart: () => {
        set({ cartItems: [] });
        notification.info('Cart cleared');
      },

      toggleCartDrawer: () => {
        set(state => ({ isCartOpen: !state.isCartOpen }));
      },

      setIsCartOpen: (isOpen) => {
        set({ isCartOpen: isOpen });
      },

      // Derived state getters
      getCartTotal: () => {
        return get().cartItems.reduce((total, item) => total + (item.price * item.quantity), 0);
      },

      getCartItemCount: () => {
        return get().cartItems.reduce((count, item) => count + item.quantity, 0);
      }
    }),
    {
      name: 'cart-storage',
      storage: createJSONStorage(() => sessionStorage),
    }
  )
);
